// Only bounded display ratios become numbers. Monetary values remain decimal strings.
export function categoryBars(categories: { amount: string | null }[]): { width: number; negative: boolean }[] {
  const scale = Math.max(0, ...categories.map(({ amount }) => amount?.split(".")[1]?.length ?? 0));
  const values = categories.map(({ amount }) => {
    if (amount === null) return 0n;
    const [whole, fraction = ""] = amount.replace(/^-/, "").split(".");
    const value = BigInt(whole + fraction.padEnd(scale, "0"));
    return amount.startsWith("-") ? -value : value;
  });
  const maximum = values.reduce((largest, value) => {
    const magnitude = value < 0n ? -value : value;
    return magnitude > largest ? magnitude : largest;
  }, 0n);
  return values.map((value) => ({ negative: value < 0n, width: maximum === 0n ? 0 : Number((value < 0n ? -value : value) * 10000n / maximum) / 100 }));
}
